// Zustand store for native timeline state management

import { nanoid } from 'nanoid'
import { create } from 'zustand'
import { subscribeWithSelector } from 'zustand/middleware'

import { debugKeyframe, debugTimeline } from '../utils/debug'
import { evaluateTrack } from './interpolation'
import type {
  BezierHandles,
  InterpolationType,
  Keyframe,
  KeyframeValue,
  SequenceState,
  SerializedTimeMarker,
  TimelineData,
  TimelineKeyframe,
  TimelineSequenceData,
  TimelineTrackData,
  TimeMarker,
  Track,
} from './types'
import { DEFAULT_BEZIER_HANDLES, DEFAULT_SEQUENCE_STATE } from './types'

// ============================================================================
// Store Interface
// ============================================================================

export interface TimelineStore {
  // === Historic State (serialized to project) ===
  sequence: SequenceState
  tracks: Map<string, Track>
  markers: TimeMarker[]

  // === Ephemeral State (session only) ===
  position: number
  playing: boolean
  loop: boolean
  loopInOut: boolean
  playbackSpeed: number
  selectedKeyframeIds: Set<string>
  selectedTrackIds: Set<string>
  selectedMarkerId: string | null
  connectingFromMarkerId: string | null

  // === Sequence Actions ===
  setLength: (length: number) => void
  setFps: (fps: number) => void

  // === In/Out Point Actions ===
  setInPoint: (time: number) => void
  setOutPoint: (time: number) => void
  clearInOutPoints: () => void

  // === Playback Actions ===
  setPosition: (position: number) => void
  play: () => void
  pause: () => void
  togglePlay: () => void
  toggleLoop: () => void
  toggleLoopInOut: () => void
  setPlaybackSpeed: (speed: number) => void
  stepForward: (frames?: number) => void
  stepBackward: (frames?: number) => void
  goToStart: () => void
  goToEnd: () => void

  // === Track Actions ===
  getOrCreateTrack: (fieldPath: string, defaultValue: KeyframeValue) => Track
  getTrack: (fieldPath: string) => Track | undefined
  getTrackById: (trackId: string) => Track | undefined
  deleteTrack: (trackId: string) => void
  deleteTracksForOperators: (operatorIds: string[]) => void
  renameTracksForOperator: (
    oldOperatorId: string,
    newOperatorId: string,
    childOperatorIds?: string[]
  ) => void
  hasKeyframesForField: (fieldPath: string) => boolean

  // === Marker Actions ===
  addMarker: (position: number) => string
  deleteMarker: (markerId: string) => void
  deleteAllMarkers: () => void
  moveMarker: (markerId: string, newPosition: number) => void
  selectMarker: (markerId: string | null) => void
  setConnectingFromMarker: (markerId: string | null) => void
  connectKeyframeToMarker: (markerId: string, trackId: string, keyframeId: string) => void
  disconnectKeyframeFromMarker: (markerId: string, keyframeId: string) => void
  getMarkerForKeyframe: (keyframeId: string) => TimeMarker | undefined

  // === Keyframe Actions ===
  addKeyframe: (trackId: string, keyframe: Omit<Keyframe, 'id'> & { id?: string }) => string
  updateKeyframe: (
    trackId: string,
    keyframeId: string,
    updates: Partial<Omit<Keyframe, 'id'>>
  ) => void
  deleteKeyframe: (trackId: string, keyframeId: string) => void
  moveKeyframe: (trackId: string, keyframeId: string, newPosition: number) => void
  setKeyframeHandles: (trackId: string, keyframeId: string, handles: BezierHandles) => void

  // Delete all currently selected keyframes in one history entry
  deleteSelectedKeyframes: () => void

  // === Selection Actions ===
  selectKeyframe: (keyframeId: string, addToSelection?: boolean) => void
  deselectKeyframe: (keyframeId: string) => void
  clearSelection: () => void
  selectAllInTrack: (trackId: string) => void
  selectTrack: (trackId: string) => void
  // Replace entire selection atomically (used by box select)
  setSelectedKeyframes: (ids: string[]) => void
  // Shift-click on track label: add all kfs if not all selected, remove all if all selected
  toggleTrackKeyframes: (trackId: string) => void
  // Select every keyframe across all tracks
  selectAllKeyframes: () => void
  // Apply easing to all currently selected keyframes (callers must fire history)
  applyEasingToSelectedKeyframes: (
    interpolation: InterpolationType,
    handles?: BezierHandles
  ) => void

  // === Evaluation ===
  evaluateTrack: (trackId: string, time?: number) => KeyframeValue | undefined
  evaluateAllTracks: (time?: number) => Map<string, KeyframeValue>

  // === Serialization ===
  toTimelineJSON: () => TimelineData
  fromTimelineJSON: (json: TimelineData, opts?: { keepPosition?: boolean }) => void
  reset: () => void
}

// ============================================================================
// Helper Functions
// ============================================================================

function generateKeyframeId(): string {
  return `kf_${nanoid(8)}`
}

function generateTrackId(): string {
  return `track_${nanoid(8)}`
}

function generateMarkerId(): string {
  return `tm_${nanoid(8)}`
}

// Keep keyframes sorted by position
function sortKeyframes(keyframes: Keyframe[]): Keyframe[] {
  return [...keyframes].sort((a, b) => a.position - b.position)
}

// Convert native handles to timeline format [leftX, leftY, rightX, rightY]
function handlesToSerialized(handles: BezierHandles): [number, number, number, number] {
  return [handles.left[0], handles.left[1], handles.right[0], handles.right[1]]
}

// Convert timeline handles to native format
function serializedToHandles(handles: [number, number, number, number]): BezierHandles {
  return {
    left: [handles[0], handles[1]],
    right: [handles[2], handles[3]],
    type: 'aligned',
  }
}

// Convert native keyframe to timeline format
function keyframeToSerialized(kf: Keyframe, index: number, total: number): TimelineKeyframe {
  return {
    id: kf.id,
    position: kf.position,
    connectedRight: index < total - 1 && kf.interpolation !== 'hold',
    handles: handlesToSerialized(kf.handles || DEFAULT_BEZIER_HANDLES),
    value: kf.value,
  }
}

// Convert timeline keyframe to native format
function serializedToKeyframe(tkf: TimelineKeyframe): Keyframe {
  return {
    id: tkf.id,
    position: tkf.position,
    value: tkf.value as KeyframeValue,
    interpolation: tkf.connectedRight ? 'bezier' : 'hold',
    handles: serializedToHandles(tkf.handles),
  }
}

// Detect value type for timeline track data
function detectValueType(value: KeyframeValue): string {
  if (typeof value === 'number') return 'BasicKeyframedTrack'
  if (typeof value === 'boolean') return 'BasicKeyframedTrack'
  if (typeof value === 'string') return 'BasicKeyframedTrack'
  if (typeof value === 'object' && value !== null) {
    if ('r' in value && 'g' in value && 'b' in value) return 'BasicKeyframedTrack'
  }
  return 'BasicKeyframedTrack'
}

// ============================================================================
// Store Creation
// ============================================================================

export const useTimelineStore = create<TimelineStore>()(
  subscribeWithSelector((set, get) => ({
    // === Initial State ===
    sequence: { ...DEFAULT_SEQUENCE_STATE },
    tracks: new Map(),
    markers: [],
    position: 0,
    playing: false,
    loop: true,
    loopInOut: false,
    playbackSpeed: 1,
    selectedKeyframeIds: new Set(),
    selectedTrackIds: new Set(),
    selectedMarkerId: null,
    connectingFromMarkerId: null,

    // === Sequence Actions ===
    setLength: length => {
      set(state => {
        const newLength = Math.max(0.1, length)
        const { outPoint } = state.sequence

        return {
          sequence: {
            ...state.sequence,
            length: newLength,
            // If outPoint is set, clamp it; otherwise leave undefined
            outPoint: outPoint !== undefined ? Math.min(outPoint, newLength) : undefined,
          },
          position: Math.min(state.position, newLength),
        }
      })
    },

    setFps: fps => {
      set(state => ({
        sequence: { ...state.sequence, fps: Math.max(1, Math.round(fps)) },
      }))
    },

    // === In/Out Point Actions ===
    setInPoint: time => {
      set(state => {
        const { sequence } = state
        const max = sequence.outPoint ?? sequence.length
        const clamped = Math.max(0, Math.min(time, max))
        return {
          sequence: { ...sequence, inPoint: clamped },
        }
      })
    },

    setOutPoint: time => {
      set(state => {
        const { sequence } = state
        const min = sequence.inPoint ?? 0
        const clamped = Math.max(min, Math.min(time, sequence.length))
        return {
          sequence: { ...sequence, outPoint: clamped },
        }
      })
    },

    clearInOutPoints: () => {
      set(state => ({
        sequence: { ...state.sequence, inPoint: undefined, outPoint: undefined },
      }))
    },

    // === Playback Actions ===
    setPosition: position => {
      const { sequence } = get()
      set({ position: Math.max(0, Math.min(position, sequence.length)) })
    },

    play: () => set({ playing: true }),
    pause: () => set({ playing: false }),
    togglePlay: () => set(state => ({ playing: !state.playing })),
    toggleLoop: () => set(state => ({ loop: !state.loop })),
    toggleLoopInOut: () => set(state => ({ loopInOut: !state.loopInOut })),

    setPlaybackSpeed: speed => {
      set({ playbackSpeed: Math.max(0.1, Math.min(10, speed)) })
    },

    stepForward: (frames = 1) => {
      const { sequence, position } = get()
      const frameTime = 1 / sequence.fps
      set({ position: Math.min(position + frameTime * frames, sequence.length) })
    },

    stepBackward: (frames = 1) => {
      const { sequence, position } = get()
      const frameTime = 1 / sequence.fps
      set({ position: Math.max(position - frameTime * frames, 0) })
    },

    goToStart: () => set({ position: 0 }),
    goToEnd: () => set(state => ({ position: state.sequence.length })),

    // === Track Actions ===
    getOrCreateTrack: (fieldPath, defaultValue) => {
      const { tracks } = get()
      let track = tracks.get(fieldPath)

      if (!track) {
        track = {
          id: fieldPath, // Use fieldPath as ID for simplicity
          fieldPath,
          keyframes: [],
          defaultValue,
        }
        const newTracks = new Map(tracks)
        newTracks.set(fieldPath, track)
        set({ tracks: newTracks })
      }

      return track
    },

    getTrack: fieldPath => get().tracks.get(fieldPath),
    getTrackById: trackId => get().tracks.get(trackId),

    deleteTrack: trackId => {
      const tracks = new Map(get().tracks)
      tracks.delete(trackId)
      // Clean up marker connections for this track
      const markers = get().markers.map(m => ({
        ...m,
        connectedKeyframes: m.connectedKeyframes.filter(c => c.trackId !== trackId),
      }))
      set({ tracks, markers })
    },

    deleteTracksForOperators: operatorIds => {
      const tracks = new Map(get().tracks)
      let changed = false
      for (const [trackId] of tracks) {
        for (const opId of operatorIds) {
          // opId is like "/my-op" or "/container/child"
          // track prefix is "my-op / " or "container / child / "
          const prefix = `${opId.slice(1).split('/').join(' / ')} / `
          if (trackId.startsWith(prefix)) {
            tracks.delete(trackId)
            changed = true
            break
          }
        }
      }
      if (changed) set({ tracks })
    },

    renameTracksForOperator: (oldOperatorId, newOperatorId, childOperatorIds) => {
      // Skip if IDs are the same (idempotent)
      if (oldOperatorId === newOperatorId) {
        return
      }

      const before = captureTimelineState()

      const tracks = new Map(get().tracks)
      const markers = [...get().markers]
      const selectedTrackIds = get().selectedTrackIds
      let changed = false
      let markersChanged = false

      // Convert operator ID to object name for matching
      // "/my-op" -> "my-op"
      // "/container/child" -> "container / child"
      const oldObjectName = oldOperatorId.slice(1).split('/').join(' / ')

      // Build the prefix to match
      const oldPrefix = `${oldObjectName} / `

      // If child operator IDs are provided, convert them to object names for checking
      const childObjectNames = new Set(
        childOperatorIds?.map(id => id.slice(1).split('/').join(' / ')) || []
      )

      // Track ID mappings for marker and selection updates
      const trackIdMap = new Map<string, string>()

      // Iterate through all tracks and rename matching ones
      for (const [oldTrackId, track] of tracks) {
        if (oldTrackId.startsWith(oldPrefix)) {
          const oldOpSegments = oldOperatorId.slice(1).split('/')
          const trackSegments = oldTrackId.split(' / ')

          // Check if the first N segments of the track match our operator path
          let isExactMatch = trackSegments.length > oldOpSegments.length
          for (let i = 0; i < oldOpSegments.length && isExactMatch; i++) {
            if (trackSegments[i] !== oldOpSegments[i]) {
              isExactMatch = false
            }
          }

          if (isExactMatch) {
            const fieldSegments = trackSegments.slice(oldOpSegments.length)

            // Check if this track belongs to a child operator
            // If we have child operator IDs, use them for exact matching
            let belongsToChild = false
            if (childObjectNames.size > 0 && fieldSegments.length >= 2) {
              // Check if adding the first field segment would form a child operator
              const potentialChildObjectName = [
                ...trackSegments.slice(0, oldOpSegments.length + 1),
              ].join(' / ')
              belongsToChild = childObjectNames.has(potentialChildObjectName)
            }

            if (!belongsToChild) {
              // This track belongs to this specific operator
              const newOpSegments = newOperatorId.slice(1).split('/')
              const newTrackId = [...newOpSegments, ...fieldSegments].join(' / ')

              const renamedTrack: Track = {
                ...track,
                id: newTrackId,
                fieldPath: newTrackId,
              }

              tracks.set(newTrackId, renamedTrack)
              tracks.delete(oldTrackId)
              trackIdMap.set(oldTrackId, newTrackId)
              changed = true
            }
          }
        }
      }

      // Update marker connections to reference new track IDs
      if (trackIdMap.size > 0) {
        for (let i = 0; i < markers.length; i++) {
          const marker = markers[i]
          const updatedConnections = marker.connectedKeyframes.map(conn => {
            const newTrackId = trackIdMap.get(conn.trackId)
            return newTrackId ? { ...conn, trackId: newTrackId } : conn
          })

          if (
            updatedConnections.some(
              (c, idx) => c.trackId !== marker.connectedKeyframes[idx].trackId
            )
          ) {
            markers[i] = { ...marker, connectedKeyframes: updatedConnections }
            markersChanged = true
          }
        }
      }

      if (changed) {
        // Update selectedTrackIds to use new track IDs
        const newSelectedTrackIds = new Set<string>()
        for (const oldTrackId of selectedTrackIds) {
          const newTrackId = trackIdMap.get(oldTrackId)
          if (newTrackId) {
            newSelectedTrackIds.add(newTrackId)
          } else if (tracks.has(oldTrackId)) {
            // Track wasn't renamed, keep the old ID
            newSelectedTrackIds.add(oldTrackId)
          }
          // If track was deleted, don't add to new selection
        }

        // Only update markers if they actually changed
        if (markersChanged) {
          set({ tracks, markers, selectedTrackIds: newSelectedTrackIds })
        } else {
          set({ tracks, selectedTrackIds: newSelectedTrackIds })
        }

        fireTimelineMutation('Rename operator tracks', before)
      }
    },

    hasKeyframesForField: fieldPath => {
      const track = get().tracks.get(fieldPath)
      return track ? track.keyframes.length > 0 : false
    },

    // === Marker Actions ===
    addMarker: position => {
      const id = generateMarkerId()
      const markers = [...get().markers, { id, position, connectedKeyframes: [] }]
      set({ markers })
      return id
    },

    deleteMarker: markerId => {
      const markers = get().markers.filter(m => m.id !== markerId)
      const selectedMarkerId = get().selectedMarkerId === markerId ? null : get().selectedMarkerId
      set({ markers, selectedMarkerId })
    },

    deleteAllMarkers: () => {
      set({ markers: [], selectedMarkerId: null })
    },

    moveMarker: (markerId, newPosition) => {
      const { markers, tracks } = get()
      const marker = markers.find(m => m.id === markerId)
      if (!marker) return

      // Move all connected keyframes maintaining their offset
      const newTracks = new Map(tracks)
      for (const conn of marker.connectedKeyframes) {
        const track = newTracks.get(conn.trackId)
        if (!track) continue
        const newKfPosition = Math.max(0, newPosition + conn.offset)
        const keyframes = track.keyframes.map(kf =>
          kf.id === conn.keyframeId ? { ...kf, position: newKfPosition } : kf
        )
        newTracks.set(conn.trackId, { ...track, keyframes: sortKeyframes(keyframes) })
      }

      // Update marker position
      const newMarkers = markers.map(m => (m.id === markerId ? { ...m, position: newPosition } : m))
      set({ markers: newMarkers, tracks: newTracks })
    },

    selectMarker: markerId => {
      set({ selectedMarkerId: markerId })
    },

    setConnectingFromMarker: markerId => {
      set({ connectingFromMarkerId: markerId })
    },

    connectKeyframeToMarker: (markerId, trackId, keyframeId) => {
      const { markers, tracks } = get()
      const marker = markers.find(m => m.id === markerId)
      const track = tracks.get(trackId)
      if (!marker || !track) return

      const keyframe = track.keyframes.find(kf => kf.id === keyframeId)
      if (!keyframe) return

      // Check if already connected to this marker
      if (marker.connectedKeyframes.some(c => c.keyframeId === keyframeId)) return

      // Remove from any other marker first
      let newMarkers = markers.map(m => ({
        ...m,
        connectedKeyframes: m.connectedKeyframes.filter(c => c.keyframeId !== keyframeId),
      }))

      // Add to the target marker
      const offset = keyframe.position - marker.position
      newMarkers = newMarkers.map(m =>
        m.id === markerId
          ? { ...m, connectedKeyframes: [...m.connectedKeyframes, { keyframeId, trackId, offset }] }
          : m
      )
      set({ markers: newMarkers })
    },

    disconnectKeyframeFromMarker: (markerId, keyframeId) => {
      const markers = get().markers.map(m =>
        m.id === markerId
          ? {
              ...m,
              connectedKeyframes: m.connectedKeyframes.filter(c => c.keyframeId !== keyframeId),
            }
          : m
      )
      set({ markers })
    },

    getMarkerForKeyframe: keyframeId => {
      return get().markers.find(m => m.connectedKeyframes.some(c => c.keyframeId === keyframeId))
    },

    // === Keyframe Actions ===
    addKeyframe: (trackId, keyframe) => {
      const tracks = new Map(get().tracks)
      const track = tracks.get(trackId)

      if (!track) {
        debugTimeline(`Track ${trackId} not found`)
        return ''
      }

      const before = captureTimelineState()

      const id = keyframe.id || generateKeyframeId()
      const newKeyframe: Keyframe = {
        id,
        position: keyframe.position,
        value: keyframe.value,
        interpolation: keyframe.interpolation || 'bezier',
        handles: keyframe.handles,
      }

      const updatedTrack = {
        ...track,
        keyframes: sortKeyframes([...track.keyframes, newKeyframe]),
      }
      tracks.set(trackId, updatedTrack)
      set({ tracks })

      debugKeyframe(
        'store.addKeyframe track=%s pos=%s id=%s value=%O',
        trackId,
        keyframe.position,
        id,
        keyframe.value
      )
      fireTimelineMutation('Add keyframe', before)
      return id
    },

    updateKeyframe: (trackId, keyframeId, updates) => {
      const tracks = new Map(get().tracks)
      const track = tracks.get(trackId)

      if (!track) return

      const keyframes = track.keyframes.map(kf =>
        kf.id === keyframeId ? { ...kf, ...updates } : kf
      )

      const updatedTrack = {
        ...track,
        keyframes: sortKeyframes(keyframes),
      }
      tracks.set(trackId, updatedTrack)
      set({ tracks })
      debugKeyframe('store.updateKeyframe track=%s id=%s updates=%O', trackId, keyframeId, updates)
    },

    deleteKeyframe: (trackId, keyframeId) => {
      const tracks = new Map(get().tracks)
      const track = tracks.get(trackId)

      if (!track) return

      const before = captureTimelineState()

      const updatedTrack = {
        ...track,
        keyframes: track.keyframes.filter(kf => kf.id !== keyframeId),
      }
      tracks.set(trackId, updatedTrack)

      // Also remove from selection
      const selectedKeyframeIds = new Set(get().selectedKeyframeIds)
      selectedKeyframeIds.delete(keyframeId)

      // Clean up marker connections
      const markers = get().markers.map(m => ({
        ...m,
        connectedKeyframes: m.connectedKeyframes.filter(c => c.keyframeId !== keyframeId),
      }))

      set({ tracks, selectedKeyframeIds, markers })
      fireTimelineMutation('Delete keyframe', before)
    },

    deleteSelectedKeyframes: () => {
      const { selectedKeyframeIds, tracks, markers } = get()
      if (selectedKeyframeIds.size === 0) return

      const before = captureTimelineState()
      const newTracks = new Map(tracks)

      for (const [trackId, track] of newTracks) {
        const filtered = track.keyframes.filter(kf => !selectedKeyframeIds.has(kf.id))
        if (filtered.length !== track.keyframes.length) {
          newTracks.set(trackId, { ...track, keyframes: filtered })
        }
      }

      // Clean up marker connections for deleted keyframes
      const newMarkers = markers.map(m => ({
        ...m,
        connectedKeyframes: m.connectedKeyframes.filter(
          c => !selectedKeyframeIds.has(c.keyframeId)
        ),
      }))

      set({ tracks: newTracks, selectedKeyframeIds: new Set(), markers: newMarkers })
      fireTimelineMutation('Delete keyframes', before)
    },

    moveKeyframe: (trackId, keyframeId, newPosition) => {
      get().updateKeyframe(trackId, keyframeId, { position: newPosition })
    },

    setKeyframeHandles: (trackId, keyframeId, handles) => {
      get().updateKeyframe(trackId, keyframeId, { handles })
    },

    // === Selection Actions ===
    selectKeyframe: (keyframeId, addToSelection = false) => {
      set(state => {
        const selectedKeyframeIds = addToSelection
          ? new Set(state.selectedKeyframeIds)
          : new Set<string>()
        selectedKeyframeIds.add(keyframeId)
        return { selectedKeyframeIds }
      })
    },

    deselectKeyframe: keyframeId => {
      set(state => {
        const selectedKeyframeIds = new Set(state.selectedKeyframeIds)
        selectedKeyframeIds.delete(keyframeId)
        return { selectedKeyframeIds }
      })
    },

    clearSelection: () => {
      set({ selectedKeyframeIds: new Set(), selectedTrackIds: new Set() })
    },

    selectAllInTrack: trackId => {
      const track = get().tracks.get(trackId)
      if (!track) return

      set({
        selectedKeyframeIds: new Set(track.keyframes.map(kf => kf.id)),
      })
    },

    selectTrack: trackId => {
      set({ selectedTrackIds: new Set([trackId]) })
    },

    setSelectedKeyframes: ids => {
      set({ selectedKeyframeIds: new Set(ids) })
    },

    toggleTrackKeyframes: trackId => {
      const { tracks, selectedKeyframeIds } = get()
      const track = tracks.get(trackId)
      if (!track || track.keyframes.length === 0) return
      const allSelected = track.keyframes.every(kf => selectedKeyframeIds.has(kf.id))
      const next = new Set(selectedKeyframeIds)
      for (const kf of track.keyframes) {
        allSelected ? next.delete(kf.id) : next.add(kf.id)
      }
      set({ selectedKeyframeIds: next })
    },

    selectAllKeyframes: () => {
      const allIds: string[] = []
      for (const [, track] of get().tracks) {
        for (const kf of track.keyframes) {
          allIds.push(kf.id)
        }
      }
      set({ selectedKeyframeIds: new Set(allIds) })
    },

    applyEasingToSelectedKeyframes: (interpolation, handles) => {
      const { tracks, selectedKeyframeIds } = get()
      for (const [trackId, track] of tracks) {
        for (const kf of track.keyframes) {
          if (selectedKeyframeIds.has(kf.id)) {
            get().updateKeyframe(trackId, kf.id, { interpolation })
            if (handles && interpolation === 'bezier') {
              get().setKeyframeHandles(trackId, kf.id, handles)
            }
          }
        }
      }
    },

    // === Evaluation ===
    evaluateTrack: (trackId, time) => {
      const track = get().tracks.get(trackId)
      if (!track) return undefined

      const evalTime = time ?? get().position
      const result = evaluateTrack(track, evalTime)
      debugKeyframe(
        'evaluateTrack %s @ t=%s kfs=%d → %O',
        trackId,
        evalTime.toFixed(3),
        track.keyframes.length,
        result
      )
      return result
    },

    evaluateAllTracks: time => {
      const { tracks, position } = get()
      const evalTime = time ?? position
      const results = new Map<string, KeyframeValue>()

      for (const [trackId, track] of tracks) {
        const value = evaluateTrack(track, evalTime)
        if (value !== undefined) {
          results.set(trackId, value)
        }
      }

      return results
    },

    // === Serialization ===
    toTimelineJSON: () => {
      const { sequence, tracks, markers } = get()

      // Group tracks by object name (operator path)
      const tracksByObject: TimelineSequenceData['tracksByObject'] = {}

      for (const [fieldPath, track] of tracks) {
        if (track.keyframes.length === 0) continue

        // Parse field path: "operator-name / prop / subprop" -> object: "operator-name", prop: "prop.subprop"
        const parts = fieldPath.split(' / ')
        const objectName = parts[0]
        const propPath = parts.slice(1).join('.')

        if (!tracksByObject[objectName]) {
          tracksByObject[objectName] = {
            trackIdByPropPath: {},
            trackData: {},
          }
        }

        const trackDataId = generateTrackId()
        tracksByObject[objectName].trackIdByPropPath[propPath] = trackDataId

        const trackData: TimelineTrackData = {
          type: detectValueType(track.defaultValue),
          keyframes: track.keyframes.map((kf, i, arr) => keyframeToSerialized(kf, i, arr.length)),
        }
        tracksByObject[objectName].trackData[trackDataId] = trackData
      }

      // Serialize markers
      const serializedMarkers: SerializedTimeMarker[] = markers.map(m => ({
        id: m.id,
        position: m.position,
        connections: m.connectedKeyframes.map(c => ({
          keyframeId: c.keyframeId,
          trackPath: c.trackId,
          offset: c.offset,
        })),
      }))

      return {
        sheetsById: {
          Noodles: {
            sequence: {
              length: sequence.length,
              subUnitsPerUnit: sequence.fps,
              tracksByObject,
              markers: serializedMarkers.length > 0 ? serializedMarkers : undefined,
              inPoint: sequence.inPoint,
              outPoint: sequence.outPoint,
            },
            staticOverrides: { byObject: {} },
          },
        },
        definitionVersion: '0.4.0',
        revisionHistory: [],
      }
    },

    fromTimelineJSON: (json, opts) => {
      const emptyTimelineState = {
        sequence: { ...DEFAULT_SEQUENCE_STATE },
        tracks: new Map<string, Track>(),
        markers: [] as TimeMarker[],
        position: 0,
        playing: false,
        selectedKeyframeIds: new Set<string>(),
        selectedTrackIds: new Set<string>(),
        selectedMarkerId: null,
        connectingFromMarkerId: null,
      }

      if (!json || typeof json !== 'object' || !json.sheetsById?.Noodles) {
        debugTimeline('Invalid timeline timeline data')
        set(emptyTimelineState)
        return
      }

      const seq = json.sheetsById.Noodles.sequence
      if (!seq) {
        // Some legacy projects only persist static overrides without a sequence.
        // Treat this as "no animated timeline" instead of an invalid project.
        set(emptyTimelineState)
        return
      }

      const newTracks = new Map<string, Track>()

      // Parse each object's tracks
      for (const [objectName, objectData] of Object.entries(seq.tracksByObject ?? {})) {
        const trackIdByPropPath = objectData?.trackIdByPropPath ?? {}
        const trackDataById = objectData?.trackData ?? {}

        for (const [propPath, trackDataId] of Object.entries(trackIdByPropPath)) {
          const trackData = trackDataById[trackDataId]
          if (!trackData) continue

          // timeline stores prop paths as JSON arrays: '["pitch"]' or '["viewState","zoom"]'
          // Fall back to dot-splitting for native-format paths like "viewState.zoom"
          let propPathParts: string[]
          try {
            const parsed = JSON.parse(propPath)
            propPathParts = Array.isArray(parsed) ? parsed.map(String) : propPath.split('.')
          } catch {
            propPathParts = propPath.split('.')
          }
          const fieldPath = [objectName, ...propPathParts].join(' / ')

          const keyframes = (trackData.keyframes ?? []).map(serializedToKeyframe)
          const defaultValue = keyframes[0]?.value ?? 0

          const track: Track = {
            id: fieldPath,
            fieldPath,
            keyframes: sortKeyframes(keyframes),
            defaultValue,
          }
          newTracks.set(fieldPath, track)
        }
      }

      // Deserialize markers
      const markers: TimeMarker[] = (seq.markers ?? []).map(m => ({
        id: m.id,
        position: m.position,
        connectedKeyframes: (m.connections ?? []).map(c => ({
          keyframeId: c.keyframeId,
          trackId: c.trackPath,
          offset: c.offset,
        })),
      }))

      const length =
        typeof seq.length === 'number' && seq.length > 0
          ? seq.length
          : DEFAULT_SEQUENCE_STATE.length

      const inPoint = typeof seq.inPoint === 'number' ? seq.inPoint : undefined
      const outPoint = typeof seq.outPoint === 'number' ? Math.min(seq.outPoint, length) : undefined

      set({
        sequence: {
          length,
          fps:
            typeof seq.subUnitsPerUnit === 'number' && seq.subUnitsPerUnit > 0
              ? Math.round(seq.subUnitsPerUnit)
              : DEFAULT_SEQUENCE_STATE.fps,
          inPoint,
          outPoint,
        },
        tracks: newTracks,
        markers,
        position: opts?.keepPosition ? get().position : 0,
        playing: false,
        selectedKeyframeIds: new Set(),
        selectedTrackIds: new Set(),
        selectedMarkerId: null,
        connectingFromMarkerId: null,
      })
    },

    reset: () => {
      set({
        sequence: { ...DEFAULT_SEQUENCE_STATE },
        tracks: new Map(),
        markers: [],
        position: 0,
        playing: false,
        loop: true,
        playbackSpeed: 1,
        selectedKeyframeIds: new Set(),
        selectedTrackIds: new Set(),
        selectedMarkerId: null,
        connectingFromMarkerId: null,
      })
    },
  }))
)

// ============================================================================
// Standalone getters (for use outside React)
// ============================================================================

export function getTimelineStore() {
  return useTimelineStore.getState()
}

export function subscribeToPosition(callback: (position: number) => void) {
  return useTimelineStore.subscribe(state => state.position, callback)
}

export function subscribeToPlaying(callback: (playing: boolean) => void) {
  return useTimelineStore.subscribe(state => state.playing, callback)
}

// ============================================================================
// Unified history integration
// ============================================================================

// Module-level callback — set by UndoRedoHandler to record timeline mutations
// into the same undo stack as node/edge operations
let _timelineMutationCallback: ((desc: string, before: string, after: string) => void) | undefined

export function registerTimelineMutationCallback(
  cb: ((desc: string, before: string, after: string) => void) | undefined
) {
  _timelineMutationCallback = cb
}

// Capture the current timeline state as a JSON string for history snapshots
export function captureTimelineState(): string {
  return JSON.stringify(useTimelineStore.getState().toTimelineJSON())
}

// Fire a history entry for a completed mutation. Pass beforeJson captured before
// the mutation; the current state is captured as "after" automatically.
export function fireTimelineMutation(desc: string, beforeJson: string) {
  if (!_timelineMutationCallback) return
  const after = captureTimelineState()
  _timelineMutationCallback(desc, beforeJson, after)
}

// Field bindings for the native timeline system
// Handles two-way synchronization between operator fields and timeline tracks

import { Temporal } from 'temporal-polyfill'
import { isHexColor } from 'validator'

import {
  BooleanField,
  ColorField,
  CompoundPropsField,
  DateField,
  type Field,
  ListField,
  NumberField,
  Point2DField,
  Point3DField,
  StringField,
  StringLiteralField,
  Vec2Field,
  Vec3Field,
} from '../noodles/fields'
import type { IOperator, Operator } from '../noodles/operators'
import { getOp } from '../noodles/store'
import { type RGBA as ColorRGBA, colorToRgba, hexToRgba, rgbaToHex } from '../utils/color'
import { debugBinding, debugKeyframe, debugTimeline } from '../utils/debug'
import type { TimelineStore } from './timeline-store'
import { getTimelineStore, useTimelineStore } from './timeline-store'
import type { KeyframeValue, Point2D, Point3D, RGBA, Vec2, Vec3 } from './types'

// Use a type alias to simplify field typing
// biome-ignore lint/suspicious/noExplicitAny: Field type requires generic parameter
type AnyField = Field<any>

// ============================================================================
// Type Guards
// ============================================================================

// Check if a field type can be animated
export function isAnimatableField(field: AnyField): boolean {
  return (
    field instanceof NumberField ||
    field instanceof BooleanField ||
    field instanceof StringField ||
    field instanceof StringLiteralField ||
    field instanceof ColorField ||
    field instanceof DateField ||
    field instanceof Vec2Field ||
    field instanceof Vec3Field ||
    field instanceof Point2DField ||
    field instanceof Point3DField ||
    field instanceof CompoundPropsField ||
    field instanceof ListField
  )
}

// ============================================================================
// Type Conversions
// ============================================================================

// Convert a field value to a keyframe value
export function fieldValueToKeyframeValue(
  field: AnyField,
  // biome-ignore lint/suspicious/noExplicitAny: Field values can be any type
  value: any
): KeyframeValue {
  // Number field - direct passthrough
  if (field instanceof NumberField) {
    return value as number
  }

  // Boolean field - direct passthrough
  if (field instanceof BooleanField) {
    return value as boolean
  }

  // String fields - direct passthrough
  if (field instanceof StringField || field instanceof StringLiteralField) {
    return value as string
  }

  // Color field - hex to RGBA (0-1 range)
  if (field instanceof ColorField) {
    if (typeof value === 'string' && isHexColor(value)) {
      return hexToRgba(value) as RGBA
    }
    if (Array.isArray(value)) {
      return colorToRgba(value) as RGBA
    }
    return value as RGBA
  }

  // Date field - Temporal to epoch milliseconds
  if (field instanceof DateField) {
    if (
      value instanceof Temporal.PlainDateTime ||
      (value && typeof value.toZonedDateTime === 'function')
    ) {
      const instant = (value as Temporal.PlainDateTime).toZonedDateTime('UTC').toInstant()
      return instant.epochMilliseconds
    }
    return value as number
  }

  // Vec2 field - normalize to object format
  if (field instanceof Vec2Field) {
    if (Array.isArray(value)) {
      return { x: value[0], y: value[1] } as Vec2
    }
    return { x: value.x, y: value.y } as Vec2
  }

  // Vec3 field - normalize to object format
  if (field instanceof Vec3Field) {
    if (Array.isArray(value)) {
      return { x: value[0], y: value[1], z: value[2] } as Vec3
    }
    return { x: value.x, y: value.y, z: value.z } as Vec3
  }

  // Point2D field - normalize to object format
  if (field instanceof Point2DField) {
    if (Array.isArray(value)) {
      return { lng: value[0], lat: value[1] } as Point2D
    }
    return { lng: value.lng, lat: value.lat } as Point2D
  }

  // Point3D field - normalize to object format
  if (field instanceof Point3DField) {
    if (Array.isArray(value)) {
      return { lng: value[0], lat: value[1], alt: value[2] } as Point3D
    }
    return { lng: value.lng, lat: value.lat, alt: value.alt } as Point3D
  }

  // Compound field - recursive conversion
  if (field instanceof CompoundPropsField) {
    const result: Record<string, KeyframeValue> = {}
    for (const [key, subField] of Object.entries(field.fields)) {
      if (value && key in value) {
        result[key] = fieldValueToKeyframeValue(subField as AnyField, value[key])
      }
    }
    return result
  }

  // Default: return as-is
  return value
}

// Convert a keyframe value back to a field value
export function keyframeValueToFieldValue(
  field: AnyField,
  kfValue: KeyframeValue
  // biome-ignore lint/suspicious/noExplicitAny: Field values can be any type
): any {
  // Number field - direct passthrough
  if (field instanceof NumberField) {
    return kfValue as number
  }

  // Boolean field - direct passthrough
  if (field instanceof BooleanField) {
    return kfValue as boolean
  }

  // String fields - direct passthrough
  if (field instanceof StringField || field instanceof StringLiteralField) {
    return kfValue as string
  }

  // Color field - RGBA to hex
  if (field instanceof ColorField) {
    const rgba = kfValue as RGBA
    return rgbaToHex(rgba as ColorRGBA)
  }

  // Date field - epoch milliseconds to Temporal
  if (field instanceof DateField) {
    const epochMs = Math.round(kfValue as number)
    return Temporal.Instant.fromEpochMilliseconds(epochMs)
      .toZonedDateTimeISO('UTC')
      .toPlainDateTime()
  }

  // Vec2/Vec3/Point fields - return as object (fields accept both)
  if (
    field instanceof Vec2Field ||
    field instanceof Vec3Field ||
    field instanceof Point2DField ||
    field instanceof Point3DField
  ) {
    return kfValue
  }

  // Compound field - recursive conversion
  if (field instanceof CompoundPropsField) {
    const kfObj = kfValue as Record<string, KeyframeValue>
    const result: Record<string, unknown> = {}
    for (const [key, subField] of Object.entries(field.fields)) {
      if (key in kfObj) {
        result[key] = keyframeValueToFieldValue(subField as AnyField, kfObj[key])
      }
    }
    return result
  }

  // Default: return as-is
  return kfValue
}

// Get the default keyframe value for a field
export function getFieldDefaultKeyframeValue(field: AnyField): KeyframeValue {
  return fieldValueToKeyframeValue(field, field.value)
}

// ============================================================================
// Path Utilities
// ============================================================================

// Convert operator ID to Theatre.js object name format
// "/my-operator" -> "my-operator", "/container/nested" -> "container / nested"
export function opIdToObjectName(opId: string): string {
  return opId.slice(1).split('/').join(' / ')
}

// Build the field path for timeline track
// Uses Theatre.js format: "objectName / fieldName / subField"
export function getFieldPath(opId: string, fieldName: string, subPath?: string[]): string {
  const objectName = opIdToObjectName(opId)
  const parts = [objectName, fieldName, ...(subPath || [])]
  return parts.join(' / ')
}

// Parse a track ID and return the corresponding operator and field
// Returns null if operator/field not found
export function getFieldFromTrackPath(fieldPath: string): {
  operator: Operator<IOperator>
  fieldName: string
  subPath?: string[]
  field: AnyField
} | null {
  const parts = fieldPath.split(' / ')
  if (parts.length < 2) return null

  // Reconstruct operator ID by trying each split point
  // "container / nested / fieldName" → try "/container/nested", then "/container"
  let operator: Operator<IOperator> | null = null
  let opPartCount = 0

  for (let i = parts.length - 2; i >= 0; i--) {
    const opId = `/${parts.slice(0, i + 1).join('/')}`
    operator = getOp(opId)
    if (operator) {
      opPartCount = i + 1
      break
    }
  }

  if (!operator) return null

  const fieldName = parts[opPartCount]
  const subPath = parts.slice(opPartCount + 1)

  // Navigate to the field
  let field: AnyField | undefined = operator.inputs[fieldName] as AnyField
  if (!field) return null

  // For compound fields, navigate to sub-field
  if (subPath.length > 0 && field instanceof CompoundPropsField) {
    field = field.fields[subPath[0]] as AnyField
  }

  if (!field) return null

  return { operator, fieldName, subPath: subPath.length > 0 ? subPath : undefined, field }
}

// ============================================================================
// Binding Management
// ============================================================================

// Track active bindings for cleanup
const activeBindings = new Map<string, () => void>()

// Bind a single field to the timeline
// Sets up two-way synchronization between field and timeline track, returns cleanup function
export function bindFieldToTimeline(
  op: Operator<IOperator>,
  fieldName: string,
  field: AnyField,
  store?: TimelineStore,
  subPath?: string[]
): () => void {
  const timelineStore = store || useTimelineStore.getState()
  const fieldPath = getFieldPath(op.id, fieldName, subPath)

  debugBinding('bind %s.%s → track %s', op.id, fieldName, fieldPath)

  // Track binding state to prevent infinite loops
  let updating = false

  // Cache for last known keyframe value
  let lastKeyframeValue: KeyframeValue | undefined

  // Get or create track for this field
  const defaultValue = getFieldDefaultKeyframeValue(field)
  timelineStore.getOrCreateTrack(fieldPath, defaultValue)

  // Subscribe to timeline position changes -> update field
  const unsubscribePosition = useTimelineStore.subscribe(
    state => state.position,
    position => {
      if (op.locked?.value || updating) return

      const value = timelineStore.evaluateTrack(fieldPath, position)
      debugBinding('pos=%s eval %s → %O', position.toFixed(3), fieldPath, value)
      if (value === undefined) return

      // Skip if value hasn't changed
      if (
        lastKeyframeValue !== undefined &&
        JSON.stringify(value) === JSON.stringify(lastKeyframeValue)
      ) {
        debugBinding('skip %s: value unchanged (%O)', fieldPath, value)
        return
      }
      lastKeyframeValue = value

      updating = true
      try {
        const fieldValue = keyframeValueToFieldValue(field, value)
        if (field.value !== fieldValue && fieldValue !== undefined) {
          debugBinding('setValue %s.%s → %O', op.id, fieldName, fieldValue)
          field.setValue(fieldValue)
        } else {
          debugBinding('skip setValue %s.%s: field already %O', op.id, fieldName, field.value)
        }
      } catch (e) {
        debugTimeline(`Error syncing timeline to field for ${op.id}.${fieldName}:`, e)
      }
      updating = false
    }
  )

  // Subscribe to track keyframe changes -> update field
  // Handles undo/redo and any other keyframe modifications
  const unsubscribeTracks = useTimelineStore.subscribe(
    state => {
      const track = state.tracks.get(fieldPath)
      return track?.keyframes
    },
    _keyframes => {
      if (op.locked?.value || updating) return

      // Re-evaluate at current position
      const position = getTimelineStore().position
      const value = timelineStore.evaluateTrack(fieldPath, position)

      if (value !== undefined) {
        // Skip if value hasn't changed
        if (
          lastKeyframeValue !== undefined &&
          JSON.stringify(value) === JSON.stringify(lastKeyframeValue)
        ) {
          return
        }
        lastKeyframeValue = value

        updating = true
        try {
          const fieldValue = keyframeValueToFieldValue(field, value)
          if (fieldValue !== undefined && field.value !== fieldValue) {
            field.setValue(fieldValue)
          }
        } catch (e) {
          debugTimeline(`Error syncing track changes to field for ${op.id}.${fieldName}:`, e)
        }
        updating = false
      }
    },
    {
      equalityFn: (a, b) => {
        if (a === b) return true
        if (!a || !b || a.length !== b.length) return false
        // Shallow compare keyframes by reference - new array is created on mutation
        return a.every((kf, i) => kf === b[i])
      },
    }
  )

  // Initial evaluation — sync field to current position when binding is established
  const initialValue = timelineStore.evaluateTrack(fieldPath)
  debugBinding('initial eval %s → %O', fieldPath, initialValue)
  if (initialValue !== undefined) {
    updating = true
    try {
      const fieldValue = keyframeValueToFieldValue(field, initialValue)
      if (fieldValue !== undefined) {
        field.setValue(fieldValue)
        lastKeyframeValue = initialValue
      }
    } catch (e) {
      debugTimeline(`Error in initial field sync for ${op.id}.${fieldName}:`, e)
    }
    updating = false
  }

  // Subscribe to field value changes -> update or create keyframe
  const fieldSub = field.subscribe((value_: unknown) => {
    debugKeyframe('field change %s.%s = %O (updating=%s)', op.id, fieldName, value_, updating)

    if (op.locked?.value || updating) {
      debugKeyframe(
        'skip %s.%s: updating=%s locked=%s',
        op.id,
        fieldName,
        updating,
        op.locked?.value
      )
      return
    }

    // Skip compound field updates to avoid infinite loops
    if (field instanceof CompoundPropsField) {
      return
    }

    updating = true
    try {
      const kfValue = fieldValueToKeyframeValue(field, value_)

      // Check if there's a keyframe at the current position
      const track = timelineStore.getTrack(fieldPath)
      // Read position from the live store — timelineStore is a snapshot and its
      // .position property would be stale if the playhead moved after bind
      const { position } = getTimelineStore()
      const epsilon = 0.001

      debugKeyframe(
        '%s: track=%s kfs=%s pos=%s',
        fieldPath,
        !!track,
        track?.keyframes.length ?? 0,
        position.toFixed(3)
      )

      const existingKf = track?.keyframes.find(kf => Math.abs(kf.position - position) < epsilon)

      if (existingKf) {
        // Update existing keyframe
        if (JSON.stringify(existingKf.value) !== JSON.stringify(kfValue)) {
          debugKeyframe(
            'update kf %s @ pos=%s id=%s %O → %O',
            fieldPath,
            position.toFixed(3),
            existingKf.id,
            existingKf.value,
            kfValue
          )
          timelineStore.updateKeyframe(fieldPath, existingKf.id, { value: kfValue })
        } else {
          debugKeyframe('skip update %s: value unchanged %O', fieldPath, kfValue)
        }
      } else if (track && track.keyframes.length > 0) {
        // Only insert keyframe if value differs from what's currently interpolated —
        // this prevents redundant keyframes when the user sets the same value
        const currentInterpolated = timelineStore.evaluateTrack(fieldPath)
        if (JSON.stringify(kfValue) !== JSON.stringify(currentInterpolated)) {
          debugKeyframe('add kf %s @ pos=%s value=%O', fieldPath, position.toFixed(3), kfValue)
          timelineStore.addKeyframe(fieldPath, {
            position,
            value: kfValue,
            interpolation: 'bezier',
          })
        } else {
          debugKeyframe(
            'skip add %s: value same as interpolated %O',
            fieldPath,
            currentInterpolated
          )
        }
      } else {
        // Note: If track has no keyframes, we don't auto-create
        // User should explicitly click the keyframe indicator to start animating
        debugKeyframe(
          'skip %s: no keyframes on track (use keyframe indicator to start animating)',
          fieldPath
        )
      }

      lastKeyframeValue = kfValue
    } catch (e) {
      debugTimeline(`Error syncing field to timeline for ${op.id}.${fieldName}:`, e)
    }
    updating = false
  })

  // Return cleanup function
  return () => {
    unsubscribePosition()
    unsubscribeTracks()
    fieldSub.unsubscribe()
  }
}

// Bind a single channel of a vector-like field to an individual number track
// Creates per-channel tracks like "op / position / x" or "op / center / lng" so each
// component can be keyframed independently
function bindVecChannelToTimeline(
  op: Operator<IOperator>,
  fieldName: string,
  field: Vec2Field | Vec3Field | Point2DField | Point3DField,
  channelKey: string,
  store?: TimelineStore
): () => void {
  const timelineStore = store || useTimelineStore.getState()
  const fieldPath = getFieldPath(op.id, fieldName, [channelKey])

  debugBinding('bind %s.%s.%s → track %s', op.id, fieldName, channelKey, fieldPath)

  let updating = false
  let lastKfValue: number | undefined

  const channelKeys = (field.constructor as typeof Vec2Field).channelKeys
  const channelIndex = channelKeys.indexOf(channelKey as (typeof channelKeys)[number])

  const getChannel = (): number =>
    field.returnType === 'tuple'
      ? ((field.value as number[])[channelIndex] ?? 0)
      : ((field.value as Record<string, number>)[channelKey] ?? 0)

  const setChannel = (val: number): void => {
    if (field.returnType === 'tuple') {
      const t = [...(field.value as number[])]
      t[channelIndex] = val
      // biome-ignore lint/suspicious/noExplicitAny: updating tuple value with channel override
      field.setValue(t as any)
    } else {
      // biome-ignore lint/suspicious/noExplicitAny: spreading vector value with channel override
      field.setValue({ ...field.value, [channelKey]: val } as any)
    }
  }

  timelineStore.getOrCreateTrack(fieldPath, getChannel())

  // Subscribe to timeline position changes -> update the field's channel
  const unsubscribePosition = useTimelineStore.subscribe(
    state => state.position,
    position => {
      if (op.locked?.value || updating) return

      const value = timelineStore.evaluateTrack(fieldPath, position) as number | undefined
      debugBinding('pos=%s eval %s → %O', position.toFixed(3), fieldPath, value)
      if (value === undefined) return

      if (lastKfValue !== undefined && value === lastKfValue) {
        debugBinding('skip %s: value unchanged (%O)', fieldPath, value)
        return
      }
      lastKfValue = value

      updating = true
      try {
        if (getChannel() !== value) {
          // Note: setChannel fans out to sibling fieldSub callbacks for every channel
          // on this field (e.g. Vec3 → 2 extra callbacks per scrub step). All siblings
          // are guarded by lastKfValue so no spurious keyframes are created.
          debugBinding('setChannel %s.%s.%s → %O', op.id, fieldName, channelKey, value)
          setChannel(value)
        }
      } catch (e) {
        debugTimeline(`Error syncing timeline to vec channel ${fieldPath}:`, e)
      }
      updating = false
    }
  )

  // Subscribe to track keyframe changes -> update channel
  const unsubscribeTracks = useTimelineStore.subscribe(
    state => {
      const track = state.tracks.get(fieldPath)
      return track?.keyframes
    },
    _keyframes => {
      if (op.locked?.value || updating) return

      const position = getTimelineStore().position
      const value = timelineStore.evaluateTrack(fieldPath, position) as number | undefined

      if (value !== undefined) {
        if (lastKfValue !== undefined && value === lastKfValue) {
          return
        }
        lastKfValue = value

        updating = true
        try {
          if (getChannel() !== value) {
            setChannel(value)
          }
        } catch (e) {
          debugTimeline(`Error syncing track changes to vec channel ${fieldPath}:`, e)
        }
        updating = false
      }
    },
    {
      equalityFn: (a, b) => {
        if (a === b) return true
        if (!a || !b || a.length !== b.length) return false
        // Shallow compare keyframes by reference - new array is created on mutation
        return a.every((kf, i) => kf === b[i])
      },
    }
  )

  // Initial evaluation — sync channel to current position when binding is established
  const initialValue = timelineStore.evaluateTrack(fieldPath, getTimelineStore().position) as
    | number
    | undefined
  debugBinding('initial eval %s → %O', fieldPath, initialValue)
  if (initialValue !== undefined) {
    updating = true
    try {
      setChannel(initialValue)
      lastKfValue = initialValue
    } catch (e) {
      debugTimeline(`Error in initial vec channel sync ${fieldPath}:`, e)
    }
    updating = false
  }
  // Seed the guard so sibling fieldSub callbacks are filtered immediately,
  // even on tracks with no keyframes (where initialValue is undefined)
  if (lastKfValue === undefined) lastKfValue = getChannel()

  // Subscribe to field value changes -> update or create a keyframe on the channel track
  // Fires for any change to the Vec2/Vec3 field; we extract only our channel's value
  const fieldSub = field.subscribe((vecValue: unknown) => {
    if (op.locked?.value || updating) return

    const kfValue =
      field.returnType === 'tuple'
        ? ((vecValue as number[])[channelIndex] ?? 0)
        : ((vecValue as Record<string, number>)[channelKey] ?? 0)

    // Skip if this channel's value hasn't changed — the Vec2/Vec3 update was caused
    // by a different channel being modified (e.g. x changed but y is still the same)
    if (lastKfValue !== undefined && kfValue === lastKfValue) return

    updating = true
    try {
      const track = timelineStore.getTrack(fieldPath)
      const { position } = getTimelineStore()
      const epsilon = 0.001

      debugKeyframe(
        '%s: track=%s kfs=%s pos=%s',
        fieldPath,
        !!track,
        track?.keyframes.length ?? 0,
        position.toFixed(3)
      )

      const existingKf = track?.keyframes.find(kf => Math.abs(kf.position - position) < epsilon)

      if (existingKf) {
        if (existingKf.value !== kfValue) {
          debugKeyframe(
            'update kf %s @ pos=%s id=%s %O → %O',
            fieldPath,
            position.toFixed(3),
            existingKf.id,
            existingKf.value,
            kfValue
          )
          timelineStore.updateKeyframe(fieldPath, existingKf.id, { value: kfValue })
        } else {
          debugKeyframe('skip update %s: value unchanged %O', fieldPath, kfValue)
        }
      } else if (track && track.keyframes.length > 0) {
        // Only insert if value differs from what the track currently interpolates —
        // this prevents redundant keyframes when another channel caused the vec update
        const currentInterpolated = timelineStore.evaluateTrack(fieldPath)
        if (kfValue !== currentInterpolated) {
          debugKeyframe('add kf %s @ pos=%s value=%O', fieldPath, position.toFixed(3), kfValue)
          timelineStore.addKeyframe(fieldPath, {
            position,
            value: kfValue,
            interpolation: 'bezier',
          })
        } else {
          debugKeyframe(
            'skip add %s: value same as interpolated %O',
            fieldPath,
            currentInterpolated
          )
        }
      } else {
        debugKeyframe(
          'skip %s: no keyframes on track (use keyframe indicator to start animating)',
          fieldPath
        )
      }

      lastKfValue = kfValue
    } catch (e) {
      debugTimeline(`Error syncing vec channel to timeline ${fieldPath}:`, e)
    }
    updating = false
  })

  return () => {
    unsubscribePosition()
    unsubscribeTracks()
    fieldSub.unsubscribe()
  }
}

// Bind all animatable fields for an operator to the timeline, returns cleanup function
export function bindOperatorToTimeline(op: Operator<IOperator>, store?: TimelineStore): () => void {
  const cleanupFns: Array<() => void> = []

  for (const [fieldName, field] of Object.entries(op.inputs)) {
    // Skip non-animatable fields
    if (typeof field.value === 'function') continue
    if (!isAnimatableField(field as AnyField)) continue

    // Vec2/Vec3 and Point2D/Point3D fields: bind each channel as an individual number
    // track so components can be keyframed independently (e.g. "op / position / x",
    // "op / center / lng")
    if (
      field instanceof Vec2Field ||
      field instanceof Vec3Field ||
      field instanceof Point2DField ||
      field instanceof Point3DField
    ) {
      const { channelKeys } = field.constructor as typeof Vec2Field
      for (const key of channelKeys) {
        const cleanup = bindVecChannelToTimeline(
          op,
          fieldName,
          field as Vec2Field | Vec3Field | Point2DField | Point3DField,
          key,
          store
        )
        cleanupFns.push(cleanup)
        activeBindings.set(`${op.id}.${fieldName}.${key}`, cleanup)
      }
      continue
    }

    // CompoundPropsField: bind each animatable sub-field individually so that
    // per-property sub-path tracks (e.g. "viewState / zoom") are evaluated
    // during scrubbing instead of the non-existent parent track.
    if (field instanceof CompoundPropsField) {
      for (const [subName, subField] of Object.entries(field.fields)) {
        if (subField instanceof CompoundPropsField || !isAnimatableField(subField as AnyField))
          continue
        const cleanup = bindFieldToTimeline(op, fieldName, subField as AnyField, store, [subName])
        cleanupFns.push(cleanup)
        activeBindings.set(`${op.id}.${fieldName}.${subName}`, cleanup)
      }
      continue
    }

    // For ListField, bind the inner field
    const actualField = field instanceof ListField ? field.field : field

    const cleanup = bindFieldToTimeline(op, fieldName, actualField as AnyField, store)
    cleanupFns.push(cleanup)

    // Track binding for later cleanup
    const bindingKey = `${op.id}.${fieldName}`
    activeBindings.set(bindingKey, cleanup)
  }

  return () => {
    for (const cleanup of cleanupFns) {
      cleanup()
    }
  }
}

// Unbind an operator from the timeline
export function unbindOperatorFromTimeline(opId: string): void {
  // Find and remove all bindings for this operator
  const keysToRemove: string[] = []
  for (const [key, cleanup] of activeBindings) {
    if (key.startsWith(`${opId}.`)) {
      cleanup()
      keysToRemove.push(key)
    }
  }
  for (const key of keysToRemove) {
    activeBindings.delete(key)
  }
}

// Bind all operators to the timeline, returns map of cleanup functions by operator ID
export function bindAllOperatorsToTimeline(
  operators: Operator<IOperator>[],
  store?: TimelineStore
): Map<string, () => void> {
  const cleanupFns = new Map<string, () => void>()

  for (const op of operators) {
    // Skip special operators
    if (op.id === '/out') continue

    const cleanup = bindOperatorToTimeline(op, store)
    cleanupFns.set(op.id, cleanup)
  }

  return cleanupFns
}

// Cleanup bindings for removed operators
export function cleanupRemovedOperators(
  currentOperatorIds: Set<string>,
  _store?: TimelineStore
): void {
  const keysToRemove: string[] = []

  for (const [key, cleanup] of activeBindings) {
    // key format is "${op.id}.${fieldName}" or "${op.id}.${fieldName}.${subName}"
    // e.g. "/my-op.value" or "/my-op.viewState.zoom" -> opId = "/my-op"
    const opId = key.split('.')[0]
    if (!currentOperatorIds.has(opId)) {
      cleanup()
      keysToRemove.push(key)
    }
  }

  for (const key of keysToRemove) {
    activeBindings.delete(key)
  }
}

// Clear all bindings (for cleanup on unmount)
export function clearAllBindings(): void {
  for (const cleanup of activeBindings.values()) {
    cleanup()
  }
  activeBindings.clear()
}
